<script setup>
import PagedRecords from './PagedRecords.vue';
import {computed} from 'vue';import {s,number,percent} from './store';defineProps({mobile:Boolean});
const plan=computed(()=>s.report.current.targetPlan);
const columns=[{key:'name',label:'Đơn vị',width:200},{key:'code',label:'Mã tracking',width:145},{key:'share',label:'Tỷ trọng mục tiêu',align:'right',width:125},{key:'target',label:'Mục tiêu đăng ký',align:'right',width:125},{key:'count',label:'Kết quả đăng ký',align:'right',width:125},{key:'completion',label:'Hoàn thành',align:'right',width:110},{key:'clevel',label:'Đăng ký C-Level',align:'right',width:125},{key:'clevel_completion',label:'C-Level / mục tiêu',align:'right',width:145}];
</script><template><section class="card stack" aria-label="Chi tiết mục tiêu"><template v-if="plan"><PagedRecords :rows="plan.rows" :all="s.exportingImage" v-slot="{rows:pageRows}"><div v-if="mobile" class="mobile-list"><article v-for="t in pageRows" :key="t.id" :class="'target-'+t.kind"><h3>{{t.name}}</h3><p class="muted">{{t.code||'Tổng hợp'}} · Tỷ trọng mục tiêu: {{percent(t.share)}}</p><p>{{number(t.count)}} / {{number(t.target)}} đăng ký · {{percent(t.completion)}}</p><p>C-Level: {{number(t.clevel)}} · {{percent(t.clevel_completion)}} mục tiêu</p></article></div><div v-else class="target-table"><MDataTable :columns="columns" :rows="pageRows" :pagination="false" :row-class="row=>'target-'+row.kind"><template v-for="key in ['target','count','clevel']" #[`cell-${key}`]="{row}">{{number(row[key])}}</template><template v-for="key in ['share','completion','clevel_completion']" #[`cell-${key}`]="{row}">{{percent(row[key])}}</template></MDataTable></div></PagedRecords></template><MEmptyState v-else type="initial" title="Chưa tìm thấy Sheet mục tiêu" description="Ứng dụng tự nhận diện và cập nhật mục tiêu từ dữ liệu bạn nhập hoặc đồng bộ."/></section></template>
